// Hand-written `knex` stub for the flowatlas fixture suite. It declares only what
// `fixtures/nest-knex-raw/src` touches, shaped like the real library so that
// `resolveTypeOrigin` sees what it sees on a real repository: the builder and the
// raw statement are both declared in `node_modules/knex`.
//
// `raw` returns a `Raw`, which is both a statement that can be awaited and a
// value a builder takes wherever it takes a column or a condition. That double
// life is the whole reason the fixture exists: the same call is a query when it
// is awaited and a fragment of another query when it is handed to a builder.

export interface Raw extends Promise<unknown> {
  readonly isRawInstance: true;
}

export interface QueryBuilder extends Promise<unknown[]> {
  where(condition: unknown, value?: unknown): QueryBuilder;
  whereIn(column: string, values: unknown): QueryBuilder;
  select(...columns: unknown[]): QueryBuilder;
  first(): Promise<unknown>;
  update(row: Record<string, unknown>): Promise<number>;
}

export interface KnexInstance {
  (table: string): QueryBuilder;
  raw(sql: string, bindings?: readonly unknown[]): Raw;
}

export declare const knex: (config?: unknown) => KnexInstance;
